const { requireWithFallback } = require('../require-package');

const { graphqlRequest } = requireWithFallback(
  require,
  '@synclistic/shopify-client/api',
  '../../../shopify-client/api'
);

function createNoopLogger() {
  return {
    info() {},
    success() {},
    warn() {},
    error() {},
    operation() {}
  };
}

function getRequest(deps = {}) {
  return deps.graphqlRequest || graphqlRequest;
}

function createResult(objectType, extras = {}) {
  return {
    objectType,
    status: extras.status || 'success',
    created: extras.created || 0,
    updated: extras.updated || 0,
    skipped: extras.skipped || 0,
    errors: extras.errors || 0,
    filepath: extras.filepath,
    dryRun: extras.dryRun || false
  };
}

module.exports = {
  createNoopLogger,
  createResult,
  getRequest
};
